const mc=(prompt,options,answer,why)=>({type:'mc',prompt,options,answer,why});
const num=(prompt,answer,unit,why,tolerance=0)=>({type:'number',prompt,answer,unit,why,tolerance});
const order=(prompt,items,answer,why)=>({type:'order',prompt,items,answer,why});
const word=(prompt,answer,why)=>({type:'text',prompt,answer,why});
const C=(id,title,en,text,formula,example,questions)=>({id,title,en,text,formula,example,questions});
const LEVELS=[];
const L=(title,en,source,lab,steps)=>{const i=LEVELS.length;LEVELS.push({title,en,source,lab,steps,world:Math.floor(i/4),icon:['grid','route','lock','bits','calc','grid','calc','flag'][Math.floor(i/4)],recap:steps.map(s=>s.title+': '+s.text).join(' ')})};
L('ما الذي نحميه؟','Security foundations','P1:4-13؛ P2:2-3،20-22؛ D2:1-3','assets',[
C('s-info','المعلومات لا تعني ملفات فقط','Information security','أمن المعلومات يحمي المعلومات والأنظمة والمعدات التي تعالجها وتخزنها وتنقلها. يشمل الورق والملفات الرقمية. الأمن في التعريف العام حالة حماية من الأخطار؛ عملياً لا يوجد وعد بانعدام كل المخاطر.','Information + Systems + Hardware','سرقة ملف ورقي سري مشكلة أمن معلومات، حتى لو لم يستعمل أحد حاسوباً.',[mc('سُرقت أوراق سرية من مكتب. هل تدخل في أمن المعلومات؟',['نعم، المعلومات الورقية مشمولة','لا، الأمن للإنترنت فقط','فقط إذا كانت PDF'],0,'تعريف المقرر يشمل المعلومات الورقية والرقمية.'),mc('أي تعريف أكمل؟',['حماية المعلومات والأنظمة والمعدات الداعمة','شراء مضاد فيروسات فقط','إخفاء كلمة السر فقط'],0,'الحماية تشمل البيانات وبيئتها، وليست أداة واحدة.')]),
C('s-components','النظام خمسة مكونات','Information systems','مكونات P1: البرامج، الأجزاء المادية، البيانات، المستخدمون، والإجراءات. البرامج تشمل التطبيقات ونظم التشغيل وأدوات الأوامر. P2 يجمع مواطن الاعتداء في أجهزة وبرامج ومعطيات واتصالات، ويؤكد دور الإنسان.','Software · Hardware · Data · People · Procedures','القرص Hardware، نظام التشغيل Software، درجات الطلبة Data، الموظف People، وتعليمات العمل Procedures.',[mc('سياسة مكتوبة لاستعادة النسخ الاحتياطية تُصنّف…',['إجراءات Procedures','أجزاء مادية','برنامج تشغيل'],0,'الإجراءات هي القواعد والخطوات المكتوبة.'),mc('نظام التشغيل والتطبيقات وأدوات الأوامر تنتمي إلى…',['Software','People','Hardware'],0,'كلها برامج، وليست معدات مادية.')]),
C('s-assets','الأصول والتطور التقني','Assets','الأصل مورد يجب حمايته: جهاز، بيانات، موقع، أو موارد بشرية. التطور في الحوسبة والاتصال وأنواع البيانات يغير الهجمات والثغرات، ويستلزم تدريباً وكوادر مؤهلة. لا تحمِ البيانات وتنسَ وسائطها.','Asset → value → appropriate protection','قبل إدخال خدمة جديدة، افحص ما تضيفه من اعتماد وثغرات، لا فائدتها الإنتاجية فقط.',[mc('قاعدة بيانات وموقع وخادم كلها أمثلة على…',['أصول Assets','هجمات','إجراءات فقط'],0,'الأصول قد تكون منطقية أو مادية.'),mc('إضافة تقنية جديدة للمؤسسة تتطلب…',['تقييم أثرها الأمني وتدريب المستخدمين','افتراض أنها تخلو من المخاطر','إلغاء كل الإجراءات'],0,'تجدد التقنية قد يضيف ثغرات ويتطلب مهارات جديدة.')])]);
L('مثلث الحماية','CIA triad','P1:20،23-24؛ P2:5-7،18-19','cia',[
C('s-conf','من يحق له أن يقرأ؟','Confidentiality','السرية تمنع كشف المعلومات لغير المخولين. الإعلان العام قد لا يحتاج سرية، بينما أرقام بطاقات الزبائن تحتاجها. الأولوية تعتمد على استخدام المعلومة.','Confidentiality = authorized disclosure','قراءة متطفل لملف دون تغيير حرف واحد تكسر السرية، حتى لو ظل الملف صحيحاً ومتاحاً.',[mc('قرأ شخص غير مخول نتائج الطلبة دون تعديلها. ما المتضرر مباشرة؟',['السرية','التوفر فقط','فائدة الملف فقط'],0,'المشكلة كشف المحتوى لغير المخول.'),mc('أي معلومة تحتاج عادة سرية أعلى؟',['بيانات بطاقة الزبون','إعلان عام','جدول دوام منشور'],0,'المستوى المطلوب يختلف بحسب الحساسية والاستخدام.')]),
C('s-integrity','هل تغير المحتوى؟','Integrity','السلامة أو التكاملية تعني حماية المعلومات من التعديل أو التلف غير المصرح به، أثناء الإدخال والمعالجة والتخزين والنقل. قد يكون السبب عمداً أو خطأً.','Integrity = protected content','تغيير مبلغ أمر شراء من100 إلى1000 يمس السلامة حتى لو كان الموقع يعمل.',[mc('تغيّر مبلغ التحويل أثناء النقل. العنصر المتضرر؟',['Integrity','Availability فقط','Possession فقط'],0,'تغيّر المحتوى هو انتهاك السلامة.'),mc('قد تضيع السلامة بسبب…',['هجوم متعمد أو خطأ غير متعمد','الهجمات المتعمدة فقط','كشف اسم المستخدم فقط'],0,'P1 يشمل التلف المتعمد وغير المتعمد.')]),
C('s-availability','هل يستطيع المخول الوصول؟','Availability','التوفر يمكّن المستخدم المخول من الوصول للخدمة والمعلومات عند الحاجة دون إعاقة. انقطاع الكهرباء أو تخريب الخدمة قد يمنعه، حتى لو لم يقرأ المهاجم شيئاً.','Availability = usable access when needed','في الخدمات المصرفية الإلكترونية، الاستمرارية مهمة إلى جانب السرية والسلامة وعدم الإنكار.',[mc('خادم متوقف يمنع الزبائن من الشراء. ما العنصر المتضرر مباشرة؟',['التوفر','السرية فقط','الأصالة فقط'],0,'تعطل الوصول للخدمة يمس التوفر.'),mc('نظام مشفر لكنه متعطل تماماً يحقق كل عناصر الأمن؟',['لا، التوفر مفقود','نعم، التشفير يكفي','نعم، لأن المحتوى مخفي'],0,'التشفير لا يضمن استمرار الخدمة.')])]);
L('خصائص لا تخلط بينها','Beyond CIA','P1:21-26؛ P2:8،18-19','qualities',[
C('s-accuracy','الدقة والأصالة','Accuracy & Authenticity','الدقة تعني خلو المعلومة من الأخطاء وحملها القيمة المتوقعة. الأصالة تعني أن مصدرها أو هويتها حقيقيان وليسا مزورين. وصول بريد باسم البنك لا يثبت أنه أرسله البنك.','Correct value ≠ genuine source','يمكن أن يصدر تقرير أصيل عن موظف معروف لكنه يحوي خطأ حسابياً؛ أصالة المصدر لا تجعل كل رقم دقيقاً.',[mc('تقرير من المصدر الصحيح يحوي خطأ جمع. أي خاصية ناقصة؟',['الدقة Accuracy','الملكية فقط','الأصالة بالضرورة'],0,'المصدر قد يكون أصيلاً مع وجود خطأ في القيم.'),mc('رسالة تنتحل اسم البنك تثير مشكلة…',['الأصالة Authenticity','عدد صفحات التقرير','سعة الذاكرة'],0,'تحتاج التحقق من المصدر الحقيقي.')]),
C('s-utility','الفائدة والسيطرة','Utility & Possession','الفائدة قيمة المعلومات لتحقيق غرض محدد، وصيغتها يجب أن تسمح باستخدامها. الملكية أو الحيازة هي التحكم بالمعلومة أو وسيطها. يمكن فقد السيطرة على وسيط مشفر دون كشف محتواه.','Utility = usefulness | Possession = control','قرص مسروق ومشفر جيداً: فقدت حيازته، لكن لا يلزم أن تكون سريته قد انكشفت. ملف موجود بصيغة غير قابلة للاستخدام قد يفتقد الفائدة.',[mc('تملك ملفاً لكن لا تستطيع استعمال صيغته لإنجاز المهمة. الخاصية الأوضح؟',['Utility','Authenticity فقط','السرية بالضرورة'],0,'وجود الملف وحده لا يجعله مفيداً للغرض.'),mc('قرص مشفر سُرق دون دليل على قراءته. ما الذي فُقد يقيناً؟',['الحيازة والسيطرة','السرية يقيناً','دقة الأرقام يقيناً'],0,'فقد السيطرة لا يثبت وحده كشف المحتوى.')]),
C('s-nonrep','منع إنكار التصرف','Non-repudiation','عدم الإنكار يعني توفير دليل ينسب تصرفاً إلى صاحبه في وقت معين، مثل أمر شراء أو توقيع. ليس هو السرية، ولا مجرد استمرار الخدمة. تعتمد قوة الدليل على النظام وإدارة المفاتيح والسياق.','Non-repudiation → evidence of an action','يمكن أن يكون التوقيع على رسالة غير مشفرة؛ إثبات صاحب التصرف لا يعني إخفاء الرسالة.',[mc('زبون ينكر إصدار طلب شراء. أي هدف يعالج هذا مباشرة؟',['عدم الإنكار','التوفر فقط','تقليل حجم البيانات'],0,'المطلوب دليل يمكن الاستناد إليه لنسبة التصرف.'),mc('هل عدم الإنكار يعني أن الرسالة مخفية عن الجميع؟',['لا، هو دليل نسبة التصرف','نعم، هو التشفير نفسه','نعم، هو النسخ الاحتياطي'],0,'السرية هدف مختلف عن إثبات التصرف.')])]);
L('فكّ لغز المخاطر','Threat · Vulnerability · Risk','P1:13-18؛ P2:40-44؛ D2:5-10','risk',[
C('s-threat','التهديد والثغرة','Threat & Vulnerability','التهديد سبب محتمل للأذى: مهاجم، حريق، أو انقطاع تيار. الثغرة ضعف يمكن أن يسمح بتحقق الضرر: إعداد خاطئ أو نقص تدريب أو غياب حماية مادية.','Threat exploits a vulnerability','الحريق تهديد، وغياب مطفأة ومخرج طوارئ ثغرة في مثال المبنى.',[mc('مستخدم لم يتلقَّ تدريباً كافياً. هذا مثال على…',['ثغرة','أصل لا يحتاج حماية','خطة تعافٍ'],0,'نقص التدريب ضعف يمكن استغلاله.'),mc('انقطاع الكهرباء حدث محتمل يضر الخدمة. هو…',['تهديد','كلمة مرور','توثيق'],0,'الحدث القادر على إحداث الضرر تهديد.')]),
C('s-risk','الاحتمال والأثر','Risk','المخاطرة تتعلق باحتمال تحقق الضرر وعواقبه، لا التهديد وحده. المصادر تستخدم Risk أحياناً بمعانٍ متقاربة وغير دقيقة؛ سنميز المصدر المحتمل والضعف والأثر. الضوابط تقلل المخاطر إلى مستوى مقبول.','Risk considers likelihood and impact','ملف درجات حساس على جهاز بلا نسخة احتياطية: حذف عارض محتمل، ضعف في الاستعداد، وأثر هو فقد البيانات.',[mc('أي وصف أدق للمخاطرة؟',['احتمال ضرر وعواقبه في سياق معين','هي جهاز الحاسوب نفسه','هي أي إجراء حماية'],0,'تمييز الاحتمال والأثر يساعد على ترتيب المعالجة.'),mc('مخاطرتان متساويتان في الاحتمال لكن أثر إحداهما أشد. هل هما متكافئتان؟',['لا، يجب النظر للأثر أيضاً','نعم دائماً','الأثر غير مهم'],0,'الاحتمال وحده لا يكفي لتقدير الأولوية.')]),
C('s-control','الضابط والحادث والهجوم','Control & Incident','Control وSafeguard وCountermeasure وسائل تقليل الخطر. الهجوم محاولة اعتداء، والحادث واقعة تمس الأمن وقد تكون متعمدة أو غير متعمدة. لا نساوي كل خطأ بخرق ناجح أو جريمة.','Control reduces risk | Incident records an event','النص P2 يضيق Incident قانونياً في موضع ويوسعه تقنياً في آخر؛ نعتمد المعنى التقني الواسع مع بيان السياق.',[mc('جدار حماية أو قفل أو تدريب يُسمى…',['ضابط أو إجراء مضاد','تهديداً دائماً','حادثاً وقع بالفعل'],0,'كلها وسائل لتقليل المخاطر.'),mc('حذف عارض لبيانات مهمة يمكن اعتباره…',['حادثاً أمنياً غير متعمد','هجوماً متعمداً بالضرورة','دليلاً على إرهاب إلكتروني'],0,'النية والنتيجة والسياق أمور مختلفة.')])]);
L('ابنِ خطة الحماية','Risk management','P2:9-19،23؛ D2:5-11','risk',[
C('s-classify','ابدأ بما تحميه','Information classification','تصنيف المعلومات يحدد حساسيتها وقيمة حمايتها. لا تتساوى كل المعلومات في المؤسسة ولا تحتاج كلها السرية نفسها. ابدأ بالأصل ثم المخاطر ثم الوسائل ثم الاستجابة.','Asset → risk → controls → response','مثال: منشور عام، سجل موظفين، وخطة سرية تتطلب مستويات مختلفة.',[mc('أول سؤال في خطة الأمن؟',['ما الذي نريد حمايته؟','أي برنامج نشتري فوراً؟','كيف نخفي كل الملفات؟'],0,'تحديد الأصل وقيمته يسبق اختيار الأداة.'),order('رتب خطوات التفكير.',['اختيار وسائل الحماية','تحديد الأصل','تحديد المخاطر'],[1,2,0],'الأصل ثم الخطر ثم الضابط المناسب.')]),
C('s-balance','حماية تناسب الغرض','Proportionate controls','وازن الأمان مع التكلفة والوقت والإنتاجية. الحماية الأضعف من الحاجة تزيد التعرض؛ التعقيد المبالغ فيه قد يعطل العمل ويشجع تجاوز الضوابط. أمثلة المحاضرة ليست منعاً مطلقاً لتعدد وسائل التحقق.','Adequate security + workable process','بنك إلكتروني يحتاج استمرارية وأدلة معاملات، لا كلمة مرور وحدها ولا تعقيداً بلا تقييم.',[mc('اختيار وسائل الأمن يجب أن يعتمد على…',['الحساسية والمخاطر والموارد والأداء','أكبر عدد أدوات فقط','الأرخص دائماً'],0,'الهدف حماية ملائمة وليست مظهراً أمنياً.'),mc('لماذا قد تضر الحماية المبالغ فيها؟',['تعطل الأداء وقد تدفع لتجاوز الإجراءات','تلغي كل مخاطر النظام','تمنع الأخطاء البشرية نهائياً'],0,'المثال يوضح أثر التعقيد على الاستخدام والالتزام.')]),
C('s-continuous','التقييم لا ينتهي','Continuous risk management','تحديد الثغرات والتهديدات والإجراءات عملية مستمرة. تتغير التقنية والتهديدات، ولا يمكن حصر كل المخاطر أو الاستعداد لكل حادث ممكن. راجع القرارات بعد التغييرات والحوادث.','Assess → act → review → repeat','لا يكفي تقييم قديم إذا تغيرت الشبكة أو أضيفت خدمة جديدة.',[mc('متى نراجع المخاطر؟',['دورياً وبعد التغيرات والحوادث','مرة عند التأسيس فقط','بعد فقد كل البيانات فقط'],0,'المقرر يصفها عملية متكررة.'),mc('هل يمكن تحديد كل المخاطر والاستعداد لها جميعاً؟',['لا، نعالجها إلى مستوى مقبول','نعم بشراء جهاز واحد','نعم بإخفاء الخوارزمية'],0,'الوقت والموارد وعدم اليقين تفرض إدارة المخاطر.')])]);
L('صنّف مصدر التهديد','Threat families','P1:27-32،38-40','threats',[
C('s-human','خطأ بلا قصد','Inadvertent acts','الأفعال غير المتعمدة تشمل أخطاء المخولين والتفاوت في جودة الخدمة وعدم استقرار الطاقة. التدريب والإجراءات الواضحة يقللان الأخطاء البشرية؛ ليس كل ضرر دليلاً على نية سيئة.','Mistake ≠ malicious intent','موظف مخول حذف صفاً بالخطأ: فعل غير متعمد.',[mc('موظف مخول حذف ملفاً بالخطأ. التصنيف؟',['غير متعمد','تجسس متعمد','تشفير زوجي'],0,'لا توجد نية سيئة في وصف الحالة.'),mc('أقرب ضابط لتقليل أخطاء العمل المتكررة؟',['تدريب وإجراءات واضحة','زيادة حجم القرص فقط','إلغاء التوثيق'],0,'المصدر يربط التدريب وضبط الخطوات بتقليل الخطأ.')]),
C('s-nature','طبيعة وطاقة وخدمة','Natural events & Power','الزلزال والبركان والإعصار تهديدات طبيعية. زيادة التيار أو انخفاضه أو انقطاعه قد تتلف المعدات أو تعطلها. تفاوت جودة الإنترنت والطاقة يؤثر في أداء المؤسسة.','Nature · service quality · power','في تصنيف P1 تدرج مشكلات مزود الخدمة والطاقة ضمن غير المتعمد؛ لا تخلطها دائماً بالتخريب.',[mc('زلزال أتلف وسائط التخزين. التصنيف؟',['طبيعي','تجسس','سرقة كلمة سر'],0,'الأصل قوة طبيعية.'),mc('اندفاع كهربائي مفاجئ قد يؤثر مباشرة في…',['المعدات واستمرارية الخدمة','ترتيب حروف بلايفر فقط','عدد مفاتيح قيصر'],0,'مشكلات الطاقة قد تتلف مكونات نظام المعلومات.')]),
C('s-failures','تقني أم إداري؟','Technical & Management failures','العطل التقني خلل مفاجئ في العتاد أو البرمجيات. الفشل الإداري نقص في التخطيط والتعامل مع العقبات وتطبيق الأمن الملائم. غياب خطة ليس عطلاً في القرص.','Broken component ≠ missing planning','تعطل قرص=تقني؛ عدم إعداد خطة نسخ وتعافٍ=إداري. قد تجتمع الفئتان في حادث واحد.',[mc('الإدارة لم تخطط للتعافي. هذا…',['فشل إداري','عطل مادي بالضرورة','هجوم سلبي'],0,'الخلل في التخطيط والمسؤوليات.'),mc('قرص توقف فجأة رغم الصيانة. الفئة المباشرة؟',['فشل تقني','تخويل','توقيع رقمي'],0,'الخلل أصاب المكون نفسه.')])]);
L('افهم الاعتداء دون تنفيذه','Attacks & effects','P1:14،33-37؛ P2:37-47','threats',[
C('s-passive','راقب أم غيّر؟','Passive vs Active','الهجوم السلبي يراقب أو يتنصت دون تعديل المحتوى أو الخدمة. النشط يغيّر أو يعطل أو ينتحل. مجرد محاولة دخول غير مصرح ليست وحدها تعريفاً جامعاً للنشط، خلاف تبسيط P1.','Passive: observe | Active: alter or disrupt','قراءة حركة مرور=سلبي؛ تعديل رسالة أو إغراق خدمة=نشط.',[mc('تنصت دون تعديل البيانات أو تعطيلها. التصنيف؟',['سلبي','نشط بالضرورة','نسخ احتياطي'],0,'التصنيف هنا حسب الفعل والأثر على البيانات والخدمة.'),mc('تغيير محتوى رسالة أثناء النقل مثال…',['نشط','سلبي','حماية مادية'],0,'المهاجم يتدخل بالتعديل.')]),
C('s-espionage','تجسس وتخريب وسرقة','Espionage · Vandalism · Theft','التجسس يكشف أسراراً إلكترونياً أو يدوياً، مثل رؤية كلمة المرور فوق الكتف. التخريب يضر العمليات أو السمعة. السرقة استيلاء غير مشروع على أصل مادي أو منطقي.','Espionage → secrecy | Vandalism → disruption','قد يمس الفعل أكثر من خاصية؛ صنف ما يصفه السيناريو مباشرة.',[mc('شخص ينظر فوق كتف موظف ليرى كلمة السر. هذا…',['تجسس','تشفير','استرجاع نسخة'],0,'التجسس قد يكون بشرياً دون برنامج.'),mc('تغيير واجهة مؤسسة بقصد تشويه سمعتها أقرب إلى…',['تخريب Vandalism','توفر مضمون','دقة أعلى'],0,'الهدف الإضرار بالعمليات أو الصورة الخارجية.')]),
C('s-legal','النية والسياق القانوني','Cybercrime terminology','المقرر يفرق بين الجريمة الإلكترونية والإرهاب الإلكتروني وحرب المعلومات، ويناقش الفرق بين السلوك غير الأخلاقي والجريمة. الوصف القانوني يتوقف على القانون والوقائع، ولا تثبته خسارة تقنية وحدها.','Cybercrime · Cyberterrorism · Information warfare','الإرهاب في العرض مرتبط بأغراض سياسية أو فكرية ونحوها؛ حرب المعلومات صراع هجمات متبادلة. لا نساوي كل منافسة أو رسالة مزعجة بالإرهاب.',[mc('هل كل خطأ تقني يعد جريمة إلكترونية تلقائياً؟',['لا، تلزم وقائع وسياق قانوني','نعم دائماً','فقط إذا كان الملف كبيراً'],0,'لا تخلط الوصف التقني بالحكم القانوني.'),mc('حرب المعلومات تشير في المحاضرة إلى…',['صراع اعتداءات وهجمات مقابلة بين جهات','أي كلمة مرور قصيرة','عملية نسخ الملفات'],0,'المقصود صراع في بيئة المعلومات، لا عطل عابر.')])]);
L('بوابات الهوية والصلاحيات','Identity & access','P2:29-31','identity',[
C('s-identify','ادّعِ هويتك ثم أثبتها','Identification & Authentication','التعريف تقديم الهوية: من تدعي أنك؟ التوثق أو المصادقة التحقق من صحة الادعاء. أما Authenticity للمصدر، وDocumentation للتوثيق المكتوب، فمصطلحان مختلفان.','Identify → authenticate → authorize','كتابة اسم المستخدم تعريف؛ التحقق من دليل الدخول مصادقة.',[mc('إدخال اسم المستخدم يحدد الهوية المدعاة. اسمه…',['Identification','Authorization','Backup'],0,'التعريف ليس إثبات صحة الهوية بعد.'),mc('التحقق من صحة دليل الهوية هو…',['Authentication','Documentation','التصنيف الطيفي'],0,'المصادقة تتحقق من الهوية المدعاة.')]),
C('s-factors','تعرف أنواع الأدلة','Authentication factors','شيء تعرفه: كلمة مرور أو PIN. شيء تملكه: بطاقة أو جهاز تحقق. شيء تكونه: بصمة إصبع أو عين أو صوت. دمج فئتين مختلفتين ليس كاستخدام كلمتي مرور.','Know · Have · Are','المصدر يذكر الجمع بين الوسائل مع الحفاظ على الفعالية وسهولة الاستخدام.',[mc('بصمة الإصبع تنتمي إلى…',['شيء تكونه','شيء تعرفه','إجراء نسخ احتياطي'],0,'خاصية حيوية مرتبطة بذات الشخص.'),mc('بطاقة مع PIN تجمع…',['شيئاً تملكه وشيئاً تعرفه','عاملين من المعرفة فقط','عامل البصمة فقط'],0,'الفئتان مختلفتان.')]),
C('s-authorize','دخلت، لكن ماذا يسمح لك؟','Authorization & Access control','بعد المصادقة يأتي تحديد ما يمكن استخدامه. التخويل يمنح صلاحيات ضمن أجزاء النظام؛ لا يعني الدخول حق تعديل كل شيء. سياسة كلمات السر تمنع الإفشاء والتخمين السهل.','Authenticated ≠ authorized for everything','موظف يستطيع قراءة سجل لكنه لا يملك حذفه؛ هذا قرار تخويل.',[mc('الحساب صحيح لكن لا يسمح له بحذف السجل. هذه مسألة…',['Authorization','تشفير بلايفر','نوع الشبكة'],0,'المنع متعلق بنطاق الصلاحيات.'),mc('مشاركة كلمة السر مع زميل تعارض…',['سياسة السرية وعدم الإفشاء','النسخ الاحتياطي فقط','حساب محدد المصفوفة'],0,'حماية دليل الدخول جزء من سياسة الهوية.')])]);
L('الأمن عمل مؤسسي','Policy · Documentation · Logging','P2:23-28،32-33','policy',[
C('s-admin','من التحليل إلى التنفيذ','Administrative responsibilities','المجموعات الخمس: تحليل المخاطر؛ السياسة وخطة الأمن؛ البناء التقني الأمني؛ توظيف المعدات والوسائل؛ تنفيذ الخطط والسياسات. مسؤولية الأمن تشمل الإدارات والأفراد والتدريب المتواصل.','Analyze → plan → design → equip → implement','التأهيل العملي لا يتوقف عند التعيين؛ يعرف كل شخص ما يجب فعله وما يحظر عليه.',[order('رتب البداية المنطقية.',['البناء التقني','تحليل المخاطر','السياسة والخطة'],[1,2,0],'التصميم يبنى على تحليل وخطة.'),mc('التدريب الأمني المناسب…',['مستمر بعد التعيين','ينتهي عند التعيين','للأجهزة دون الأشخاص'],0,'تغير العمل والتهديدات يستلزم مواصلة التدريب.')]),
C('s-document','وثّق قبل الأزمة','Documentation','دوّن بناء النظام والتعريف والتخويل وتصنيف المعلومات والسياسة والمسؤوليات وخطط الحوادث والتعافي. التوثيق المكتوب يحفظ الإجراءات ويحدد المسؤولية؛ ليس هو المصادقة على هوية مستخدم.','Written policy + clear responsibilities','خطة موجودة في ذاكرة موظف واحد ليست بديلاً عن إجراء موثق يمكن للجهة المسؤولة اتباعه.',[mc('خطة استجابة مكتوبة ومسؤوليات محددة مثال…',['Documentation','Authentication فقط','هجوم سلبي'],0,'هنا التوثيق كتابي.'),mc('لماذا نوثق إجراءات الحفظ؟',['لتوحيد التنفيذ والمسؤوليات والاسترجاع','لإلغاء الحاجة للنسخ','لمنع أي حادث نهائياً'],0,'التوثيق يسمح باتباع معيار واضح.')]),
C('s-logs','أعد بناء ما حدث','Logging','السجلات قد تحدد من استخدم النظام ومتى وأين وماذا فعل. تشمل سجلات أمن ونظام وتطبيقات وقواعد بيانات وتبادل وصيانة، وقد تكون تاريخية أو مؤقتة. احمِ السجلات وراعِ الخصوصية.','Who · When · Where · What','سجل النفاذ يساعد التحليل بعد الحادث؛ لا يغني عن النسخة الاحتياطية للبيانات.',[mc('أداة تساعد على معرفة المستخدم ووقت العملية؟',['Logging','حذف السجلات','زيادة الإزاحة في قيصر'],0,'هذا الغرض الموصوف لسجل الأداء.'),mc('هل سجل الاستخدام نسخة كاملة بديلة لكل بيانات المؤسسة؟',['لا، غرضه التتبع والتحليل','نعم دائماً','نعم إذا طالت أسطره'],0,'النسخ الاحتياطي والتسجيل وظيفتان مختلفتان.')])]);
L('استجب للحادث','Incident handling','P2:17،35-36؛ D2:التعافي','incident',[
C('s-prepare','استعداد وكشف','Preparation & Detection','التعامل مع الحوادث عملية مستمرة بقواعد ومسؤوليات محددة مسبقاً، لا مهمة تبدأ من الصفر عند الضرر. أولاً استعداد، ثم تحرٍّ وملاحظة لاكتشاف ما حصل.','Prepare → detect','تختلف التفاصيل حسب المخاطر والتطبيق، لكن غياب الخطة نفسه نقطة ضعف.',[mc('متى نبني إجراءات الاستجابة؟',['قبل الحادث مع مراجعتها باستمرار','فقط بعد انتهاء الأزمة','لا حاجة لمسؤوليات'],0,'الاستعداد المسبق أساسي في المصدر.'),mc('التحري والملاحظة يهدفان إلى…',['اكتشاف الحادث وفهم علاماته','إعلان التعافي فوراً','إخفاء كل الأدلة'],0,'الكشف يسبق اختيار إجراءات المعالجة.')]),
C('s-contain','حدّ الانتشار ثم أزل السبب','Containment & Eradication','الاحتواء يحد الضرر أو الانتشار. الاستئصال يزيل السبب أو المكونات الخبيثة. لا تخلط الحد المؤقت للضرر بإصلاح دائم، ولا تفترض أن إعادة التشغيل وحدها تزيل المشكلة.','Contain → eradicate','في محاكاة تعليمية: عزل جهاز مشتبه به احتواء؛ إزالة سبب الإصابة بعد التحليل استئصال.',[mc('عزل جهاز مشتبه به للحد من الانتشار يسمى…',['احتواء','متابعة نهائية','إثبات عدم الإنكار'],0,'الهدف المؤقت حصر الضرر.'),mc('إزالة سبب الإصابة بعد تحديده أقرب إلى…',['استئصال','تصنيف المعلومات','تعريف المستخدم'],0,'الاستئصال يعالج السبب لا مجرد أثره.')]),
C('s-recover','استعد وتعلّم','Recovery & Follow-up','بعد المعالجة تُستعاد الخدمة للوضع الطبيعي مع التحقق، ثم المتابعة وتحسين الوقاية. نستخدم ترتيب المحاضرة الستّي، مع التنبيه أنه نموذج المقرر وليس النموذج الوحيد للاستجابة.','Prepare → detect → contain → eradicate → recover → follow up','تعافٍ دون معالجة السبب قد يعيد الحادث. المتابعة تستفيد من التحليل لمنع التكرار.',[order('رتب مراحل ما بعد الكشف.',['التعافي','الاحتواء','الاستئصال','المتابعة'],[1,2,0,3],'حصر الضرر، إزالة السبب، استعادة الخدمة، ثم المتابعة.'),mc('لماذا نتابع بعد رجوع الخدمة؟',['للتعلم وتحسين الضوابط ومنع التكرار','لإلغاء كل السجلات','لإثبات أن أي خطر اختفى للأبد'],0,'الاستجابة عملية تحسين مستمرة.')])]);
L('الشبكة والخدمة','Networks & denial of service','D1:1-9،Packet Sniffers؛ P2:21','network',[
C('s-networks','شارك الموارد وافهم النطاق','LAN · MAN · WAN','الشبكة تربط الحواسيب لتبادل البيانات ومشاركة الملفات والطابعات وموارد أخرى. LAN محلية، MAN حضرية، WAN واسعة. وردت MAN باسم Medium/عنكبوتية في الملف؛ المقصود Metropolitan Area Network.','LAN → MAN → WAN (typical scope)','قد تستخدم الاتصالات أسلاكاً أو كوابل أو أقماراً صناعية؛ الحماية تشمل الاتصال ذاته.',[mc('شبكة تربط مكاتب ضمن مبنى أقرب إلى…',['LAN','WAN بالضرورة','Hash'],0,'النطاق المحلي هو LAN.'),mc('التوسيع الصحيح للاختصار MAN؟',['Metropolitan Area Network','Medium Antivirus Number','Memory Access Name'],0,'وصف MAN في الوثيقة يحتاج تصحيحاً اصطلاحياً.')]),
C('s-dos','خدمة لا تصل للمستخدم','DoS & DDoS','حجب الخدمة يعوق الاستخدام بإرهاق الخدمة أو تعطيلها. في الهجوم الموزع تأتي حركة الهجوم من أجهزة متعددة. الهدف المباشر التوفر؛ لا يعني الاسم بالضرورة سرقة المحتوى.','DoS → availability | DDoS → distributed sources','الثغرات والإعداد الخاطئ قد تتيح إساءة استخدام الخادم. ندرس التصنيف والدفاع فقط، دون تنفيذ هجمات.',[mc('أجهزة متعددة تُستخدم لتعطيل خدمة. المصطلح؟',['DDoS','نسخ احتياطي','Caesar'],0,'Distributed تعني موزع المصدر.'),mc('العنصر المتضرر مباشرة بحجب الخدمة؟',['Availability','Authenticity فقط','عدد مستويات الرمادي'],0,'المستخدم لا يستطيع الوصول للخدمة.')]),
C('s-sniff','راقب حركة المرور بحذر','Packet sniffers','التقاط الحزم قد يساعد على تشخيص الشبكة والكشف عن نشاط مشتبه به، وقد يستخدم للتنصت. لا يعني الالتقاط وحده كشف كل محتوى مشفر؛ الغرض والتصريح والحماية تحدد السياق.','Network monitoring ≠ automatic decryption','الخادم والمتصفح يتبادلان معلومات؛ ترك الثغرات مكشوفة يزيد الخطر. المراقبة المشروعة لا تبرر اعتراض الآخرين دون إذن.',[mc('أداة التقاط حزم قد تفيد في…',['تحليل المرور وتشخيص الشبكة المصرح بها','ضمان فك كل تشفير','إلغاء الحاجة للتحديث'],0,'النص يذكر فائدتها التشخيصية والدفاعية.'),mc('هل رؤية حركة مشفرة تعني بالضرورة قراءة محتواها؟',['لا','نعم دائماً','فقط إذا كانت LAN'],0,'التقاط البيانات وفك تشفيرها عمليتان مختلفتان.')])]);
L('عائلة البرمجيات الخبيثة','Malware families','D1:فيروسات الكمبيوتر والتصنيفات؛ P1:37','malware',[
C('s-virus','الفيروس والدودة وطروادة','Virus · Worm · Trojan','الفيروس يدرج نسخاً منه في ملفات أو برامج مضيفة. الدودة تنتشر بين الأنظمة بآلياتها. طروادة تتظاهر بفائدة أو تخفي وظيفة ضارة. ليست كل برمجية خبيثة فيروساً بالمعنى الدقيق.','Malware is the umbrella term','برامج الدعاية تظهر إعلانات، والتجسس يجمع معلومات. قد تكون البرمجية مزعجة أو تسرق بيانات أو تعطل العمل.',[mc('برنامج يتظاهر بأنه مفيد ويخفي وظيفة ضارة أقرب إلى…',['Trojan','نسخة احتياطية','ملف توقيع سليم'],0,'طروادة تتخفى ضمن وظيفة تبدو مشروعة.'),mc('هل كل برنامج خبيث فيروس تقنياً؟',['لا، الفيروس نوع من Malware','نعم، لا فرق','الفيروس جهاز مادي'],0,'المصطلح الأشمل هو Malware.')]),
C('s-filevirus','إصابة الملفات وتكرارها','File viruses','يذكر الملف الإصابة بحقن كود في ملف تنفيذي، ونمط تكرار الملفات الذي يستهلك التخزين. قد تحاول أداة المكافحة إصلاح الملف المصاب أو عزله، حسب الحالة؛ ليست استعادة كل ملف مضمونة.','Infect a host ≠ duplicate files','أسماء Sality وMabezat وTemp.exe أمثلة تاريخية بالمصدر، وليست قائمة تهديدات حالية شاملة.',[mc('إضافة كود خبيث داخل ملف تنفيذي أقرب إلى…',['إصابة ملف مضيف','تصنيف الحساسية','توقيع مشروع'],0,'المصدر يصف حقن الكود ضمن الملف.'),mc('نسخ متكررة من ملفات كثيرة قد تستنزف…',['مساحة التخزين','عدد حروف الأبجدية','محدد مصفوفة المفتاح'],0,'التكرار يزيد الحجم المطلوب للحفظ.')]),
C('s-specialvirus','إقلاع وماكرو وسكربت','Boot · Macro · Script','فيروس الإقلاع يستهدف بيئة الإقلاع. الماكرو مرتبط ببرامج تدعم تعليمات ماكرو مثل Office. السكربت يستخدم لغة أو مفسراً. ليست فيروسات الإقلاع محصورة دائماً بالأقراص المرنة، ولا كل مستند يصيب الجهاز بمجرد فتحه.','Boot environment · macro execution · script execution','عبارات الوثيقة عن الندرة والإصابة التلقائية قديمة أو مطلقة؛ السلوك يتوقف على المحتوى والتنفيذ والضوابط.',[mc('مستند Office يضم ماكرو خبيثاً ينتمي إلى…',['Macro malware','MAN','Playfair'],0,'التصنيف متعلق بآلية الماكرو.'),mc('أي عبارة أدق؟',['فيروسات الإقلاع ليست محصورة مطلقاً بالأقراص المرنة','كل مستند Office فيروس','كل ماكرو مسموح وآمن'],0,'نصحح التعميم التاريخي في المصدر.')])]);
L('صنّف دور طروادة','Trojan roles','D1:أحصنة طروادة','malware',[
C('s-backdoor','مدخل خفي أم إدارة مشروعة؟','Backdoor & RAT','الباب الخلفي يتيح وصولاً غير مشروع أو متجاوزاً للضوابط. أدوات الإدارة عن بعد قد تكون مشروعة؛ التصريح والسياق أساسيان. بعض البرمجيات الخبيثة تمنح تحكماً خفياً أو صلاحيات واسعة.','Authorization separates legitimate administration from abuse','قد يشمل الضرر الوصول للملفات أو سرقة البيانات أو التحكم بالجهاز؛ لا نجرب هذه الأفعال على أنظمة حقيقية.',[mc('أداة إدارة عن بعد يستخدمها مسؤول بتصريح واضح…',['ليست خبيثة لمجرد أنها عن بعد','طروادة بالضرورة','تشفير أحادي الاتجاه'],0,'نوع الاستخدام والتصريح مهمان.'),mc('وصول خفي يتجاوز آلية الدخول أقرب إلى…',['Backdoor','Backup','Hash'],0,'هو باب وصول غير مشروع أو متجاوز للضوابط.')]),
C('s-pswspy','كلمات السر أم نشاط أوسع؟','PSW Trojan & Spyware','سارق كلمات السر يستهدف بيانات الاعتماد. التجسس قد يجمع نشاطاً أوسع مثل الصور أو نشاط الشاشة. General Trojan تسمية واسعة لأدوار ضارة متنوعة؛ قد تجمع برمجية واحدة أكثر من وظيفة.','PSW → credentials | Spy → activity','ليس كل تجسس محصوراً بكلمات المرور، وليس كل نشاط مراقبة مشروعاً دون تصريح.',[mc('وظيفته الأساسية سرقة كلمات المرور. التصنيف؟',['PSW Trojan','مرشح متوسط','قرص بصري'],0,'PSW في المصدر مرتبط بكلمات السر.'),mc('جمع نشاط الشاشة يتجاوز كلمات السر وحدها. أقرب إلى…',['Spyware / Trojan Spy','مفتاح تماثلي','سجل رسمي بالضرورة'],0,'المراقبة الخفية للنشاط دور تجسسي.')]),
C('s-clickproxy','نقرات ووساطة اتصال','Clicker & Proxy Trojan','Clicker يعيد توجيه المتصفح أو يولد زيارات غير مرغوبة. Proxy Trojan يستعمل جهاز الضحية وسيط اتصال. قد تمنع برمجية خبيثة الوصول لمواقع الحماية؛ الاسم يصف وظيفة لا ضماناً لحصر الضرر.','Clicker → visits | Proxy → relay','نربط السلوك بالدور في سيناريوهات مغلقة، دون إنشاء زيارات أو وسطاء حقيقيين.',[mc('استعمال جهاز الضحية وسيطاً لمرور اتصالات أقرب إلى…',['Proxy Trojan','Median','Information classification'],0,'Proxy يعني وسيط اتصال.'),mc('إعادة التوجيه إلى مواقع دون رغبة المستخدم أقرب إلى…',['Clicker','نسخة احتياطية','شهادة موثوقة'],0,'هذه وظيفة يذكرها المصدر لنوع Clicker.')])]);
L('تحميل وإخفاء واستنزاف','Payload & concealment roles','D1:Downloaders إلى ArcBombs','malware',[
C('s-loader','يجلب أم يضع حمولة؟','Downloader & Dropper','Downloader يجلب حمولة من مصدر آخر. Dropper يضع أو يثبت حمولة يحملها أو يفكها. قد تستخدم أساليب إخفاء؛ وصف المصدر للتغيير في التوقيع تبسيط، والتوقيع هنا بصمة كشف لا توقيع مرسل.','Downloader fetches | Dropper delivers','الفرق الدراسي هو وظيفة الحصول على الحمولة وتوصيلها، وليس قياساً ثابتاً لحجم البرنامج.',[mc('برنامج صغير يجلب ملفاً ضاراً آخر. وظيفته؟',['Downloader','Authenticator','Playfair'],0,'يجلب الحمولة من مصدر آخر.'),mc('مكوّن يضع حمولة ضارة مضمّنة معه أقرب إلى…',['Dropper','MAN','Backup'],0,'إيصال أو تثبيت الحمولة دوره الأساسي.')]),
C('s-rootnotify','إخفاء النشاط أم الإبلاغ؟','Rootkit & Notifier','Rootkit يخفي نشاطاً أو وجود مكونات خبيثة وقد يرتبط بصلاحيات مرتفعة. Notifier يبلّغ المشغّل بوقوع إصابة أو بمعلومات عن الجهاز. قد يجتمع الدوران مع أدوار أخرى.','Rootkit hides | Notifier reports','عمل إدارة المهام لا يثبت غياب برمجية خبيثة؛ قد تُخفى بعض الأنشطة.',[mc('إخفاء عمليات خبيثة عن أدوات النظام أقرب إلى…',['Rootkit','نسخة آمنة','تشفير قيصر'],0,'الدور المقصود إخفاء الوجود أو النشاط.'),mc('مكوّن يخبر المشغّل بنجاح الإصابة أقرب إلى…',['Notifier','مرشح إعلانات مشروع بالضرورة','مصفوفة مرافقة'],0,'المصدر يصفه للإشعار بوقوع الإصابة.')]),
C('s-arcbomb','حجم صغير لا يعني عبئاً صغيراً','Archive bomb','قنبلة الأرشيف قد تستهلك موارد هائلة عند فك محتوى يتوسع بشدة. الملف يذكر تكرار البيانات وإفساد الأرشيفات وضغط محتوى كبير جداً. ندرس أثر الاستنزاف، ولا ننشئ ملفات مؤذية.','Small compressed size ≠ small expanded size','مرفق صغير قد يكون مكلفاً في الذاكرة أو التخزين أو وقت المعالجة.',[mc('أرشيف صغير يتمدد إلى حجم هائل يهدد…',['الموارد والتوفر','الأصالة فقط','عدد مفاتيح قيصر'],0,'التوسع قد يستنزف قدرة الخدمة أو الجهاز.'),mc('الحكم على أمان المرفق من حجمه المضغوط فقط…',['غير كافٍ','دليل قاطع','بديل للتحديث'],0,'الحجم قبل الفك لا يمثل كل عبء المعالجة.')])]);
L('اختر طبقات الحماية','Defense & recovery','P2:33-34؛ D1:سبل الحماية والتحديث والنسخ','defense',[
C('s-firewall','فرز المرور أم كشف الحوادث؟','Firewall & IDS','جدار الحماية يضبط المرور وفق قواعد. IDS يكتشف أو ينبه إلى نشاط مشتبه به. لا يضمن جدار الحماية كشف كل فيروس ولا يلغي الحاجة للمكافحة والتحديث.','Firewall filters | IDS detects','النص القديم يجمع مكافحة الفيروسات والترشيح في وصف واحد؛ نفصل الوظائف مع الحفاظ على فكرة الدفاع بطبقات.',[mc('منع اتصال وفق سياسة المرور وظيفة…',['Firewall','بلايفر','النسخة الاحتياطية'],0,'جدار الحماية ينفذ قواعد المرور.'),mc('إصدار تنبيه عن نشاط مشتبه به وظيفة أقرب إلى…',['IDS','تقليل مستويات الرمادي','المصفوفة المرافقة'],0,'IDS نظام تحري أو كشف اختراق.')]),
C('s-antivirus','فحص وإصلاح وعزل','Antimalware & Updates','المكافحة تفحص ملفات وأنشطة وتحاول المعالجة أو العزل. التحديث يعالج ثغرات ويحدث أساليب الكشف. لا توجد أداة تضمن منع كل إصابة، ولا قائمة شركات قديمة تصلح توصية دائمة.','Scan · repair if possible · quarantine · update','التوقيعات مهمة لكن الكشف ليس توقيعات فقط. يحدث النظام والبرامج؛ إعادة التشغيل تتبع متطلبات التحديث لا قاعدة يومية مطلقة.',[mc('ملف مصاب لا يمكن إصلاحه بأمان قد يحتاج…',['عزلاً وفق الأداة والإجراء','نشره لبقية الأجهزة','تعطيل المكافحة'],0,'العزل أحد الخيارات المذكورة في الملف.'),mc('التحديث مهم لأنه…',['يعالج ثغرات ويواكب تهديدات جديدة','يجعل كل ملف موثوقاً','يغني عن النسخ الاحتياطي'],0,'لا يغني تحديث الأداة عن بقية الضوابط.')]),
C('s-backup','احتفظ بما يمكنك استعادته','Backup & Restore','حدد وقت النسخ ومكانها الآمن وترقيمها وآلية الاسترجاع وحماية السرية. أبقِ نسخة منفصلة عن الأصل، واختبر إمكان الاستعادة. لا تصل وسيط النسخ بجهاز مشتبه بإصابته دون إجراء آمن.','Backup + protection + tested restore','سرقة الجهاز أو تلف القرص أو حذف عارض أو كارثة قد تفقد البيانات. النسخة في الموضع نفسه معرضة للحادث نفسه.',[mc('أفضل وصف لنسخ موثوقة؟',['دورية ومحمية ومنفصلة وقابلة للاستعادة','نسخة مجهولة لم تختبر','نسخة على القرص المعطل نفسه فقط'],0,'الحفظ يجب أن يصحبه استرجاع وحماية.'),mc('لماذا قد نُشفّر النسخة الاحتياطية؟',['لحماية سرية ما تحويه','لإلغاء الحاجة لكلمة المفتاح','لمنع تلف القرص مادياً'],0,'النسخ تتطلب حماية السرية كذلك.')])]);
L('قرارات المستخدم اليومية','Privacy & social engineering','D1:Phishing والبريد والنوافذ والتنزيل؛ D2:Privacy','privacy',[
C('s-phishing','تحقق قبل الإفشاء','Phishing','التصيد ينتحل جهة موثوقة لطلب معلومات أو دفعك لفعل ضار. لا تثق بالاسم الظاهر أو بمعرفة المرسل لبعض التفاصيل. تحقق عبر قناة مستقلة معروفة، ولا ترسل كلمة سر أو بيانات حساسة استجابة لطلب مريب.','Claimed identity ≠ verified identity','رسالة عاجلة تطلب كلمة السر باسم البنك: صنفها وتحقق دون استخدام رابطها. المحاكاة لا تتصل بأي جهة.',[mc('رسالة باسم البنك تطلب كلمة السر فوراً. التصرف الأفضل؟',['التحقق بقناة مستقلة وعدم الإفشاء','إرسال كلمة السر','تصديق الاسم الظاهر'],0,'هذا نمط تصيد؛ الاسم وحده ليس إثباتاً.'),mc('قد تصل مرفقات ضارة من حساب صديق لأن…',['الحساب أو الرسالة قد يكونان مخترقين أو منتحلين','كل الأصدقاء مهاجمون','وجود المرسل يضمن الأمان'],0,'المصدر ينبه إلى عدم كفاية معرفة اسم المرسل.')]),
C('s-privacy','الخصوصية ليست مجرد تشفير','Internet privacy','الخصوصية قدرة الشخص على التحكم بما ينشر عنه. تشمل بيانات محددة للهوية مثل الاسم وتاريخ الميلاد والعنوان، وغير مباشرة مثل سلوك التصفح. التشفير يحمي محتوى، ولا يضمن وحده عدم كشف الهوية.','Content confidentiality ≠ anonymity','الأسماء المستعارة والصور المختلفة لا تضمن إخفاء الهوية، وقد تخالف شروط خدمة. أمثلة الحقوق والقانون بالمصدر ليست فتوى قانونية محلية.',[mc('تشفير الرسالة وحده يضمن إخفاء هوية مستخدمها؟',['لا','نعم دائماً','فقط مع قيصر'],0,'الهوية قد تظهر من بيانات أخرى أو من السياق.'),mc('تاريخ الميلاد والاسم الحقيقي يُعدان…',['بيانات يمكن أن تحدد الشخص','ضوابط أمنية','خوارزميات تشفير'],0,'المقرر يفرق بين بيانات الهوية والسلوك.')]),
C('s-email','البريد والتنزيل والنوافذ','Email & downloads','احذر المرفقات والروابط والتنزيل من مصادر غير موثوقة. لا تضغط موافقة داخل نافذة مريبة. تشفير البريد قد يحمي المحتوى، لكنه لا يجعل الجهاز المصاب سليماً أو المرفق آمناً.','Verify source · assess content · keep defenses active','قول المصدر إن الخطر لا يقع إلا بفتح المرفق مطلق وغير دقيق؛ كما أن المجانية لا تعني الخبث تلقائياً، ولا الترشيح يضمن السلامة.',[mc('نافذة غير متوقعة تطلب تثبيت أداة. القرار المناسب؟',['عدم الموافقة والتحقق من المصدر','التثبيت فوراً','إيقاف كل التحديثات'],0,'لا تمنح الثقة لطلب غير متوقع.'),mc('قناة مشفرة إلى جهاز مصاب تضمن حماية كل البيانات على الجهاز؟',['لا','نعم دائماً','نعم إذا كان البريد قصيراً'],0,'حماية النقل لا تصلح تلقائياً نقطة النهاية المصابة.')])]);
L('ماذا يفعل التشفير؟','Cryptography foundations','P5:3-8،10،28؛ P4:3','crypto-flow',[
C('s-plain','قبل التحويل وبعده','Plaintext & Ciphertext','Plaintext هو النص الأصلي، وCiphertext ناتج التشفير. Encryption يحول للأخير، وDecryption يستعيد الأصل باستخدام الطريقة والمفتاح المناسبين. Cryptanalysis تحليل قد يستنتج معلومات دون امتلاك السر.','P → E(K,P)=C → D(K,C)=P','الخوارزمية خطوات التحويل، والمفتاح مدخل يحدد التحويل. ليس كل مفتاح كلمة مرور بشرية.',[mc('النص قبل التشفير اسمه…',['Plaintext','Ciphertext','Firewall'],0,'الصريح هو المدخل قبل التحويل.'),mc('استعادة النص الصريح من المشفر بالوسيلة المقررة تسمى…',['Decryption','Logging','Classification'],0,'فك التشفير يعكس التحويل ضمن النظام الصحيح.')]),
C('s-keyalgo','المفتاح ليس الخوارزمية','Key & Algorithm','يمكن أن تكون الخوارزمية معلنة بينما يعتمد النظام على سرية مفتاحه. معرفة النص الصريح والمشفر والخوارزمية لا تضمن استنتاج مفتاح تشفير قوي؛ ملاحظة P5 عن أي ثلاثة عناصر ليست قاعدة عامة.','Public algorithm ≠ public secret key','قيصر ضعيف فيمكن تجربة إزاحاته؛ لا تعمم ذلك على الخوارزميات القوية.',[mc('هل معرفة الخوارزمية والنصين تكشف كل مفتاح دائماً؟',['لا','نعم هذه قاعدة لكل تشفير','فقط لأن النص إنجليزي'],0,'ملاحظة الثلاثة عناصر في الشريحة8 تعميم خاطئ.'),mc('ما الذي يجب حمايته في التشفير المتماثل؟',['المفتاح السري','اسم الخوارزمية وحده','اللغة المستخدمة فقط'],0,'المفتاح السري هو المدخل الواجب حمايته.')]),
C('s-cryptogoals','أهداف وقيود مختلفة','Security services','علم التعمية يدعم السرية والسلامة والمصادقة وعدم الإنكار بآليات مختلفة. التشفير وحده لا يضمنها جميعاً. الإخفاء يخفي وجود رسالة، والاستبدال يغير رموزها، والتحليل الإحصائي أداة تحليل لا ضمان حماية.','Encryption alone ≠ every security service','المصدر يذكر الأخطاء البشرية وضعف الشفرة والهجمات غير المنطقية؛ نوضح الأخيرة كاعتداء على الأشخاص أو الإجراءات بدلاً من كسر الرياضيات.',[mc('رسالة مشفرة فقط تعني بالضرورة أنها لم تُعدّل؟',['لا','نعم دائماً','فقط إن كان طولها زوجياً'],0,'السرية لا تساوي ضمان السلامة.'),mc('خداع حامل المفتاح بدلاً من كسر الخوارزمية يستهدف…',['الأشخاص والإجراءات','محدد المصفوفة فقط','عدد حروف اللغة فقط'],0,'الخطأ البشري قد يبطل حماية رياضية جيدة.')])]);
L('اختر نموذج المفاتيح','Symmetric & asymmetric','P5:9-11،15-16','keys',[
C('s-symmetric','نفس السر للعملية وعكسها','Symmetric cryptography','التشفير المتماثل يستخدم سراً مشتركاً للتشفير وفكه. تسميته «تشفير المفتاح العام» في P5 خطأ. أمثلته المذكورة Caesar وDES و3DES وAES وIDEA وBlowfish، لكنها ليست جميعاً خيارات حديثة آمنة.','same secret key → encrypt/decrypt','المشاركة الآمنة بالمفتاح تحدٍّ مهم. لا تختزل قوة النظام في وجود مفتاح واحد أو اثنين.',[mc('متماثل يعني…',['مفتاحاً سرياً مشتركاً للعملية وعكسها','مفتاحاً عاماً بالضرورة','دالة بلا مفتاح دائماً'],0,'سرية المفتاح المشترك أساس هذا النموذج.'),mc('هل مجرد وجود مفتاحين يجعل النظام أقوى دائماً؟',['لا، تعتمد القوة على الخوارزمية والمفاتيح والتنفيذ','نعم بلا استثناء','يعتمد على لون الواجهة'],0,'مقارنة الشريحة16 تبسيط لا قاعدة مطلقة.')]),
C('s-asymmetric','زوج مرتبط من المفاتيح','Asymmetric cryptography','يوجد مفتاح عام وخاص مرتبطان. في مثال تشفير الرسائل: يُستخدم العام للمستلم للتشفير، والخاص المقابل للفك. لا نعكس ذلك ونعتبره وصفاً لكل توقيع وخوارزمية.','Recipient public → encrypt | recipient private → decrypt','RSA وElGamal أمثلة. DSA للتوقيع وDiffie–Hellman لاتفاق المفاتيح؛ PGP منظومة تجمع آليات، لا خوارزمية واحدة.',[mc('لإرسال رسالة سرية إلى ليلى، تستخدم في النموذج العام…',['مفتاح ليلى العام','مفتاحك العام فقط','مفتاح ليلى الخاص المنشور'],0,'يفكها المستلم بمفتاحه الخاص.'),mc('Diffie–Hellman يُعرف أساساً بأنه…',['اتفاق مفاتيح','فيروس ملفات','اسم آخر لـMD5'],0,'القائمة في العرض تخلط وظائف تعمية مختلفة.')]),
C('s-keytrade','سرعة وتوزيع وأمان','Trade-offs','المتماثل عادة مناسب لكميات البيانات الكبيرة من حيث الكفاءة، وغير المتماثل يساعد في التبادل والتوقيع. التوزيع والثقة وسرية الخاص وجودة الخوارزمية مهمة؛ لا تساوِ السرعة بضعف الأمن.','Different roles, different trade-offs','التشفير الحديث قد يجمع النموذجين. المفاتيح العامة تنشر، بينما الخاص لا يُنشر.',[mc('أي مفتاح في الزوج غير المتماثل يجب إبقاؤه سرياً؟',['الخاص','العام دائماً','كلاهما يجب نشرهما'],0,'الخاص سر لصاحبه؛ العام قابل للنشر.'),mc('المتماثل أسرع عادة، هل يعني أنه أضعف دائماً؟',['لا','نعم بالضرورة','لا يحتاج أي مفتاح'],0,'الأمان يقيم النظام والخوارزمية والإدارة لا الاسم وحده.')])]);
L('عجلة قيصر','Caesar cipher','P5:12-14','caesar',[
C('s-caesarmap','الحرف عدد على حلقة','Alphabet mapping','نمثل A=0 إلى Z=25. قيصر يضيف إزاحة k مع الالتفاف؛ المثال بالمحاضرة k=3. Z لا يخرج من الأبجدية، بل يلتف إلى بدايتها.','C=(P+k) mod26','A مع3 تصبح D، وZ مع3 تصبح C.',[word('شفّر A بإزاحة3.','D','A=0؛0+3=3 والحرف D.'),word('شفّر Z بإزاحة3.','C','Z=25؛28 mod26=2 والحرف C.')]),
C('s-caesarencrypt','شفّر ثم اعكس الإزاحة','Encrypt & decrypt','في التشفير أضف k؛ في الفك اطرح k ثم خذ باقي القسمة غير السالب. المسافات قد تبقى للقراءة. لا تخلط ترميز الأرقام مع عدد الإزاحات.','P=(C−k) mod26','MR CARTER IS A COOL TEACHER → PU FDUWHU LV D FRRO WHDFKHU مع3.',[word('شفّر CAT بإزاحة3.','FDW','C→F وA→D وT→W.'),word('فك FDW بإزاحة3.','CAT','نطرح3 من كل حرف مع الالتفاف.')]),
C('s-caesarkeys','قليل المفاتيح وكثير الأنماط','Key space & frequency','26 إزاحة ممكنة إذا حسبنا الصفر، و25 إزاحة غير تافهة. الخوارزمية والفك معروفان، وتكرار الحروف وشكل اللغة يساعدان التحليل. هو مثال تعليمي وليس حماية حديثة.','26 total shifts | 25 nonzero shifts','تجربة إزاحات لعبة قصيرة لا تعني أن كل نظم التشفير قابلة للتجربة بهذه السهولة.',[num('عدد إزاحات قيصر غير الصفرية؟',25,'','نستبعد إزاحة0 من26.'),mc('لماذا قيصر ضعيف؟',['فضاء مفاتيحه صغير ويحفظ أنماط التكرار','لأن خوارزميته يجب أن تبقى سرية','لأنه يستخدم26حرفاً فقط'],0,'صغر عدد البدائل وبقاء الأنماط يسهّلان التحليل.')])]);
L('من الرسالة إلى بصمة','Hash & MD5 structure','P5:17-20','hash',[
C('s-hash','تلخيص، لا تشفير قابل للفك','Cryptographic hash','دالة التجزئة تنتج بصمة من بيانات. لا يوجد لها فك عام يعيد الأصل كما في التشفير بمفتاح. تسمية «تشفير باتجاه واحد» اصطلاح في الشرائح؛ سنميز Hash عن Encryption القابل للاسترجاع.','message → digest','نفس البصمة قد تقابل مدخلات مختلفة؛ اختزال بيانات طويلة إلى حجم ثابت يفرض وجود تصادمات.',[mc('هل MD5 له مفتاح فك يعيد الرسالة الأصلية؟',['لا، هو دالة تجزئة','نعم، العام دائماً','نعم، بإزاحة3'],0,'التجزئة ليست تشفيراً قابلاً للعكس.'),mc('المدخل نفسه دون تغيير يعطي…',['البصمة نفسها لدالة حتمية','بصمة عشوائية كل مرة','النص الأصلي بعد فك'],0,'حتمية الخرج خاصية مهمة للتجزئة.')]),
C('s-md5size','أحجام يجب تمييزها','MD5 block & output','MD5 يعالج كتل512بت بعد التهيئة والحشو، كل كتلة16كلمة من32بت. البصمة128بت، تمثل عادة32رمزاً ست عشرياً. حجم الكتلة ليس حجم الخرج.','512=16×32 | 128=32×4','MD5 لعبارة Message Digest 5 هو211b88402ac7072606ec70f190ba5dd0، مع حساسية دقيقة للبايتات.',[num('طول بصمة MD5 بالبت؟',128,'bits','128بت تمثل عادة32رمزاً ست عشرياً.'),num('كم رمزاً ست عشرياً يمثل128بت؟',32,'رمزاً','كل رمز ست عشري4بت؛128÷4=32.')]),
C('s-md5rounds','تتبع الهيكل','MD5 processing','التسلسل الدراسي: تهيئة وحشو، كتل512بت، تقسيم كل كتلة إلى16كلمة32بت، أربع جولات بعمليات منطقية، ثم بصمة128بت. الحشو جزء لازم وإن أغفلته خلاصة الشريحة.','Pad → blocks → words → 4 rounds → digest','المرجع التفصيلي يحفظ أحجام المحاضرة؛ لا نستنتج نوع أي خوارزمية من طول128بت وحده.',[num('عدد كلمات32بت في كتلة512بت؟',16,'كلمة','512÷32=16.'),num('عدد الجولات المذكور في هيكل MD5؟',4,'جولات','الشريحة20 تشير لأربع جولات.')])]);
L('اقرأ البصمة بعقل ناقد','Collisions & password checks','P5:21-22،25-27؛ تصحيح RFC6151','hash',[
C('s-collision','التساوي ليس برهان التطابق','Collision','تصادم يعني مدخلين مختلفين يعطيان البصمة نفسها. عبارة P5 بأن MD5 لا يتصادم خاطئة. كذلك طول128بت لا يثبت أن الدالة MD5. MD5 غير مقبول حيث تلزم مقاومة التصادم مثل التواقيع الرقمية.','Different inputs can share a digest','اختلاف البصمتين يثبت اختلاف البيانات المدخلة؛ تساويهما لا يبرهن التطابق منطقياً. مرجع التصحيح RFC6151.',[mc('بصمتا MD5 متساويتان. هل يثبت ذلك تطابق الملفين قطعاً؟',['لا، التصادم ممكن','نعم دائماً','يعني أنهما مشفران بالمفتاح نفسه'],0,'القول المطلق في الشريحة21 خطأ.'),mc('خرج128بت يثبت وحده استخدام MD5؟',['لا','نعم','فقط إذا كتب بست عشري'],0,'أكثر من دالة يمكن أن تنتج الطول نفسه.')]),
C('s-filehash','ماذا تثبت المقارنة؟','File integrity checks','احسب بصمة مرجعية موثوقة ثم قارنها بلاحقة. اختلافهما يكشف اختلاف المحتوى، لكنه لا يحدد وحده الفاعل أو السبب. إذا استطاع المهاجم تغيير الملف والمرجع معاً، فالمقارنة لا تعطي الثقة المطلوبة.','Trusted baseline → recompute → compare','الحفاظ على سلامة المرجع أساسي. MD5 مناسب هنا لدراسة فكرة المقرر، وليس توصية للتحقق الأمني من خصم.',[mc('بصمة ملف تغيرت عن مرجع موثوق. الاستنتاج؟',['المدخلات اختلفت','نعرف هوية المهاجم يقيناً','كل الملفات مصابة'],0,'الاختلاف لا يحدد السبب أو الشخص وحده.'),mc('المهاجم غيّر الملف والبصمة المرجعية معاً. هل مقارنة الاثنين كافية؟',['لا، المرجع لم يعد موثوقاً','نعم دائماً','لا نحتاج المرجع أصلاً'],0,'يجب حماية المرجع من التلاعب.')]),
C('s-passwordhash','مقارنة تخمين لا فك تعمية','Passwords & guess checking','مثال الشرائح يقارن بصمة كلمة مدخلة بالمخزنة. القاموس يجرب كلمات متوقعة، وBrute force فضاء مرشحات، وRainbow tables بيانات محسوبة مسبقاً. هذا ليس فك MD5 رياضياً. تخزين كلمات السر بـMD5 الخام غير مناسب.','Guess → hash → compare','للتطبيقات الفعلية تستخدم مخططات كلمات مرور مخصصة مع salt وتكلفة. عدد المحاولات والإغلاق سياسة نظام لا خاصية ثابتة لـMD5.',[mc('مطابقة بصمة كلمة مرشحة للمخزنة هي…',['اختبار تخمين','فك عام لكل بصمة','حساب معكوس مصفوفة'],0,'نحسب البصمة للمرشح ونقارن، لا نعكس الدالة.'),mc('ثلاث محاولات ثم إغلاق الحساب في الشريحة…',['سياسة مثال لا خاصية MD5','قانون رياضي للدالة','دليل استحالة التخمين'],0,'ضبط المحاولات مستقل عن خوارزمية التجزئة.')])]);
L('أثبت المصدر والتصرف','Digital signatures','P5:6،23-24؛ P2:8','signature',[
C('s-sign','الخاص يوقع والعام يتحقق','Signing vs encrypting','التوقيع ينشأ بالمفتاح الخاص للمرسل ويُتحقق منه بالعام المقابل. هذا مختلف عن تشفير رسالة سرية بالعام للمستلم. ليست كل خوارزمية توقيع مجرد «تشفير بصمة».','sender private → sign | sender public → verify','نشرح رسم المحاضرة كمخطط مبسط، مع فصل الهدف والوظيفة.',[mc('أي مفتاح يستخدمه المرسل لإنشاء توقيعه؟',['الخاص به','الخاص بالمستلم','أي مفتاح عام'],0,'المفتاح الخاص ينشئ توقيع صاحبه.'),mc('للتحقق من توقيع المرسل تستخدم…',['مفتاحه العام الموثوق','مفتاحك الخاص فقط','كلمة سر الملف دائماً'],0,'المفتاح العام المقابل يتحقق من التوقيع.')]),
C('s-signflow','لخّص ووقّع وتحقق','Signature workflow','المخطط: تلخيص الرسالة، إنشاء توقيع، إرسال الرسالة والتوقيع، ثم التحقق وحساب التلخيص للمقارنة. يجب الوثوق بربط المفتاح بهوية صاحبه؛ الشهادة الرقمية إحدى آليات هذا الربط.','hash → sign → send → verify','الشريحة تستخدمMD5 تاريخياً؛ التصحيح أنه لا يصلح لتوقيعات تتطلب مقاومة التصادم.',[order('رتب مخطط الإرسال المبسط.',['إرسال الرسالة والتوقيع','حساب تلخيص الرسالة','إنشاء التوقيع'],[1,2,0],'نلخص ثم نوقع ثم نرسل.'),mc('لماذا يهم الوثوق بربط المفتاح العام بالمرسل؟',['لئلا نتحقق بمفتاح منتحل','لأن العام يجب إخفاؤه دائماً','لإلغاء الحاجة للتوقيع'],0,'الثقة في الهوية لا تأتي من وجود مفتاح عام مجهول.')]),
C('s-signlimits','موقّع لا تعني مخفي','Signature limits','يمكن توقيع رسالة غير مشفرة. التوقيع يدعم إثبات المصدر وسلامة الرسالة وعدم الإنكار ضمن شروطه، لكنه لا يوفر السرية وحده. لا تتساوى صورة توقيع باليد مع توقيع تعموي.','Signed ≠ encrypted','P5:24 يحتوي رسماً للتوقيع المرسل والتحقق لدى المستقبل، لا قاعدة لفك أي تشفير.',[mc('رسالة موقعة لكنها غير مشفرة قد تكون…',['مقروءة مع إمكانية التحقق من التوقيع','سرية بالضرورة','بلا أي بايتات'],0,'السرية ليست وظيفة التوقيع وحده.'),mc('صورة توقيع باليد هي دائماً توقيع تعموي؟',['لا','نعم','فقط لو كانت PNG'],0,'التوقيع التعموي مرتبط بخوارزمية ومفاتيح وتحقق.')])]);
L('ابنِ مربع بلايفر','Playfair key square','P3:3-7،24','playfair',[
C('s-pfsquare','خمسة في خمسة','5×5 square','بلايفر يشفر أزواج حروف. المربع25خانة، وندمج I/J في النسخة المدروسة. نمسح تكرار المفتاح مع حفظ أول ظهور، ثم نكمل الأبجدية دونJ.','25 cells | I/J share a cell','المفتاح MONARCHY يبدأ المربع بصف MONAR، ثم CHYBD. تطوير ويتستون وترويج بلايفر خلفية تاريخية بالمصدر.',[num('عدد خانات مربع بلايفر5×5؟',25,'خانة','5×5=25؛ لذلك تدمج I/J.'),mc('أي حرفين مدمجان في النسخة المدروسة؟',['I وJ','A وB','X وQ'],0,'نحول J إلى I عند تجهيز النص.')]),
C('s-pfkey','احذف تكرار المفتاح فقط','Key deduplication','في المفتاح نحتفظ بأول ظهور لكل حرف. PLAYFAIR تصبح PLAYFIR. هذه ليست قاعدة حذف الحروف المكررة من الرسالة؛ للرسالة سياسة حشو مختلفة.','PLAYFAIR → PLAYFIR','بعد المفتاح نضيف بقية الأبجدية بترتيبها، ثم نملأ صفاً بعد صف.',[word('المفتاح PLAYFAIR بعد حذف التكرار؟','PLAYFIR','نحذف A الثانية ونحافظ على ترتيب أول ظهور.'),word('المفتاح BALLOON بعد حذف تكراره فقط؟','BALON','أول ظهور: B ثمA ثمL ثمO ثمN.')]),
C('s-pflocate','ثبت الصف والعمود','Positions','الصف من أعلى إلى أسفل والعمود من اليسار لليمين. في مربع MONARCHY: M=(1,1)، D=(2,5)، S=(4,4). حدد الموقعين قبل اختيار القاعدة.','Position=(row,column)','لا تعرف القاعدة من قرب الحروف في الأبجدية، بل من مواقعها في مربع المفتاح.',[num('رقم عمود D في مربع MONARCHY؟',5,'','D في الصف2 العمود5.'),num('رقم صف S في المربع نفسه؟',4,'','S في الصف4 العمود4.')])]);
L('جهّز الأزواج دون إسقاط','Playfair preparation','P3:8-12،23-25','playfair',[
C('s-pfnormal','نظف ثم كوّن أزواجاً','Normalize & pair','نحول لحروف كبيرة ونزيل غير الحروف في نموذجنا، ثم J→I. التقسيم من اليسار إلى اليمين، لكن الحشو قد يغير الأزواج التالية؛ لا تقسم مرة واحدة ثم تحذف المكرر.','clean → J→I → pair sequentially','النص SECRET MESSAGE يصبح SECRETMESSAGE قبل تجهيز الأزواج.',[word('نظف JIG إلى النسخة التي تدمج I/J.','IIG','J تتحول إلى I. هذه مرحلة تنظيف قبل إدخال الحشو.'),mc('هل نحذف حرفاً أصلياً مكرراً من الرسالة؟',['لا، ندخل حشواً ثم نتابع','نعم مثل المفتاح دائماً','نحذف كل X'],0,'حذف تكرار المفتاح لا يطبق على الرسالة.')]),
C('s-pfrepeat','أعد التقسيم بعد الحشو','Repeated-letter pairs','إذا تساوى حرفا الزوج، نخرج الأول وحرف الحشو ثم نعيد النظر من الحرف الثاني الأصلي. BALLOON تصبح BA LX LO ON. لا نسقط L أوO.','BALLOON → BALXLOON','HELLO → HE LX LO. COMMITTEE → CO MX MI TX TE EX.',[word('جهز BALLOON مع حشو X. اكتب الحروف دون فواصل.','BALXLOON','BA ثمLX ثمLO ثمON؛ تغير التقسيم بعد الحشو.'),word('جهز HELLO.','HELXLO','HE ثمLX ثمLO.')]),
C('s-pffill','آخر حرف وحالة X','Padding edge cases','أكمل الحرف المنفرد بحشو. إذا كان X منفرداً أو مكرراً، نستخدم Q بدلاً من تكوينXX في لعبتنا. بعد الفك لا تحذف كلX آلياً؛ قد يكون أصلياً ولا يستعاد I/J يقيناً دون سياق.','CAT→CATX | ABX→ABXQ','ABCX زوجي فلا يحتاج حشواً؛ ABC→AB CX. لا يمكن تمييز كل حشو من النص وحده دون سياسة أو معلومات إضافية.',[word('جهز CAT بحشو X.','CATX','CA ثمTX.'),word('جهز ABX مع Q بديلاً حين يكون المنفردX.','ABXQ','AB ثمXQ؛ لا ننشئXX.')])]);
L('قواعد مربع بلايفر','Row · Column · Rectangle','P3:13-17،20-21','playfair',[
C('s-pfrow','نفس الصف','Same row','في التشفير نستبدل الحرف بما على يمينه ونلتف من الأخير للأول. الفك يساراً. حافظ على ترتيب الحرفين. كل الأمثلة هنا بمفتاح MONARCHY.','Encrypt: right | decrypt: left','MO→ON، وAR→RM بالتفاف R إلىM.',[word('شفّر MO بمفتاح MONARCHY.','ON','M→O وO→N؛ نفس الصف.'),word('شفّر AR بالمفتاح نفسه.','RM','A→R وR→M بالتفاف.')]),
C('s-pfcol','نفس العمود','Same column','في التشفير ننزل خانة ونلتف من الأسفل للأعلى. في الفك نصعد. هذه القاعدة لا تستعمل عندما يختلف العمودان.','Encrypt: down | decrypt: up','MC→CE، وUL→MU في مربع MONARCHY.',[word('شفّر MC بمفتاح MONARCHY.','CE','M→C وC→E؛ نفس العمود.'),word('شفّر UL بالمفتاح نفسه.','MU','U→M بالتفاف وL→U.')]),
C('s-pfrect','بدّل العمودين فقط','Rectangle','إذا اختلف الصف والعمود، يأخذ كل حرف عمود الآخر مع الحفاظ على صفه. القاعدة نفسها للفك، وليست تبديل الصفوف أو عكس ترتيب الحرفين.','(r1,c1),(r2,c2) → (r1,c2),(r2,c1)','MD→RC؛ IN→GA. اعثر على زاويتي المستطيل الأخريين.',[word('شفّر MD بمفتاح MONARCHY.','RC','من صفM وعمودD نأخذR؛ ومن صفD وعمودM نأخذC.'),word('شفّر IN بالمفتاح نفسه.','GA','I وN في مستطيل؛ نحافظ على الصفين ونبدل العمودين.')])]);
L('أكمل بلايفر وراجعه','Playfair full messages','P3:18-30','playfair',[
C('s-pffull','رسالة المحاضرة كاملة','INSTRUMENTS','جهز IN ST RU ME NT SX. طبق القاعدة لكل زوج واجمع بالترتيب: GA TL MZ CL RQ XA. لا تضف أو تحذف حرفاً وسط الحساب دون تفسير سياسة الحشو.','INSTRUMENTS → GATLMZCLRQXA','المفتاح MONARCHY. اختبار مستقل: شفّر الزوج الأول ثم الأخير وتأكد من حفظ الترتيب.',[word('شفّر INSTRUMENTS كاملاً بمفتاح MONARCHY.','GATLMZCLRQXA','الأزواج: IN ST RU ME NT SX؛ الخرج GA TL MZ CL RQ XA.'),word('شفّر SECRET MESSAGE بمفتاح SECURITY.','ECUSTFVTUQUIFC','SE CR ET ME SX SA GE → EC US TF VT UQ UI FC. تسميات الاتجاه في شريحة الحل معكوسة لكن الخرج يتبع اليمين والأسفل.')]),
C('s-pfdecrypt','اعكس الاتجاه لا الحشو تلقائياً','Playfair decryption','قسم المشفر إلى أزواج كما هو، وطبق اليسار للصف والأعلى للعمود والمستطيل نفسه. راجع الحشو بعد الحساب، ولا تجهز المشفر كما تجهز الصريح.','GATLMZCLRQXA → INSTRUMENTSX','إزالة X الأخيرة في المثال معروفة من سياق الرسالة، وليست ترخيصاً لحذف كلX.',[word('فك ON بمفتاح MONARCHY.','MO','نفس الصف؛ نرجع يساراً.'),word('فك GATLMZCLRQXA واكتب الناتج قبل إزالة الحشو.','INSTRUMENTSX','بعد الفك يبقى حشوX حتى تراجعه وفق السياسة.')]),
C('s-pfsecurity','أقوى تاريخياً لا آمناً حديثاً','Digraph analysis','25×24=600زوج مرتب من حرفين مختلفين. بلايفر يشتت تكرار الحرف الواحد، لكن تكرار الأزواج يساعد التحليل. لا يوفر وحده سلامة الرسالة أو إثبات المرسل، وليس مناسباً لحماية بيانات حقيقية.','AB→XY implies BA→YX','في هذا النموذج لا زوج متطابق، ولا يتحول حرف إلى نفسه؛ هذه خصائص تعليمية قد تفيد التحليل.',[num('عدد الأزواج المرتبة من25حرفاً دون زوج متطابق؟',600,'زوج','25×24=600.'),mc('هل بلايفر مناسب وحده لحماية بيانات حساسة حديثاً؟',['لا','نعم لأنه يستخدم زوجين','نعم لأن المربع سري'],0,'يبقى قابلاً للتحليل الإحصائي ولا يقدم كل خدمات الأمن.')])]);
L('لغة هيل الرياضية','Hill mapping & modular arithmetic','P4:4-9','hill',[
C('s-hillmap','من الحروف للأعداد','A=0…Z=25','هيل، الذي قدمه Lester S. Hill عام1929، يستخدم الجبر الخطي لتشفير كتل حروف. A=0 وH=7 وE=4 وL=11 وP=15. لا تستعمل A=1 في أمثلة هذا المقرر.','HELP → 7,4,11,15','تحويل الحروف إلى أعداد مرحلة ترميز؛ ضرب المصفوفة هو مرحلة التشفير.',[num('رقم الحرف H وفق A=0؟',7,'','H هو الحرف الثامن لكن ترميزه يبدأ من0.'),num('رقم الحرف P وفق الترميز نفسه؟',15,'','P يقابل15، لا16.')]),
C('s-mod','باقي القسمة غير السالب','Mod26','نأخذ باقي القسمة على26 لإبقاء القيم بين0و25. للسالب نضيف مضاعفات26 حتى يقع في المجال. لا نقسم الناتج ونستعمل الجزء العشري.','33 mod26=7 | −9 mod26=17','في الكود نستخدم mod مزدوجاً لضمان قيمة غير سالبة إذا اختلف سلوك باقي القسمة بين اللغات.',[num('33 mod26 يساوي؟',7,'','33=26+7.'),num('−9 mod26 في المجال0..25؟',17,'','−9+26=17.')]),
C('s-hillblock','حجم المفتاح يحدد الكتلة','Blocks & vectors','مفتاح2×2 يعمل على كتلة حرفين. نستخدم متجهات عمودية في هذا المقرر. HELP تقسم HE وLP؛ لا تجمع كل كلمة في متجه أربعة عناصر مع مفتاح2×2.','P=[p1;p2] | C=KP mod26','مصفوفة أوسع تحتاج كتلة مناسبة؛ لا تخلط ضرب المتجه العمودي باتفاق آخر دون تحويل القاعدة.',[mc('المفتاح2×2 في أمثلتنا يشفر في كل مرة…',['حرفين','حرفاً واحداً دائماً','26حرفاً'],0,'بعدا المفتاح يحددان طول متجه الكتلة.'),word('اكتب أزواج HELP بالترتيب دون فواصل.','HELP','الأزواج HE ثمLP؛ لا تعكس ترتيبهما.')])]);
